SELECT CASE WHEN dept_name IN ('Legal', 'Finance') THEN 'core' ELSE 'other' END AS dept_name_group, location, CASE WHEN budget >= 4137000 THEN 'high' WHEN budget >= 911000 THEN 'mid' ELSE 'low' END AS budget_bucket, ROUND(STDDEV(budget), 2) AS stddev_budget, COUNT(budget) AS budget_count, ROUND(AVG(budget), 2) AS avg_budget FROM departments GROUP BY dept_name_group, location, budget_bucket
